import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.cZsgxozV.js";var i=JSON.parse(`{"title":"s3haim custom Markdown","description":"","frontmatter":{},"headers":[],"relativePath":"custom-markdown/index.md","filePath":"custom-markdown/index.md"}`),a={name:`custom-markdown/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n('<h1 id="s3haim-custom-markdown" tabindex="-1">s3haim custom Markdown <a class="header-anchor" href="#s3haim-custom-markdown" aria-label="Permalink to “s3haim custom Markdown”">​</a></h1><p>md-editor-rt / markdown-it / CommonMark <strong>기본 문법</strong>이 아닌, 이 앱에서 추가·확장한 문법만 모은다.</p><p>전역 플러그인 등록: <code>src/config/mdEditorConfig.js</code> (<code>main.jsx</code>에서 import).</p><p>각 feature 문서는 <strong>문법 예시</strong>와 함께, 다른 Markdown 파서에서도 동일하게 구현할 수 있는 <strong>Spec (interop)</strong> 을 포함한다.</p><h2 id="문서-목록" tabindex="-1">문서 목록 <a class="header-anchor" href="#문서-목록" aria-label="Permalink to “문서 목록”">​</a></h2><table tabindex="0"><thead><tr><th>문서</th><th>문법</th><th>영역</th></tr></thead><tbody><tr><td><a href="./wiki-image.html">wiki-image.md</a></td><td><code>![[path|opts]]</code> + 캡션</td><td>에디터 / 미리보기 / 채팅 / 인쇄</td></tr><tr><td><a href="./remote-image.html">remote-image.md</a></td><td><code>&lt;!-- remote-image … --&gt;</code> sidecar</td><td>서식 유지 복사 / ImgBB</td></tr><tr><td><a href="./markdown-image-attrs.html">markdown-image-attrs.md</a></td><td><code>![alt](src){attrs}</code></td><td>에디터 / 미리보기 / 인쇄</td></tr><tr><td><a href="./page-break.html">page-break.md</a></td><td><code>&lt;pgbr/&gt;</code></td><td>에디터 / 인쇄·PDF</td></tr><tr><td><a href="./heading-levels.html">heading-levels.md</a></td><td><code>#######</code> … <code>##########</code> (h7–h10)</td><td>에디터 / Novel / 인쇄</td></tr><tr><td><a href="./chat-file.html">chat-file.md</a></td><td><code>[[file:…]]</code></td><td>채팅</td></tr><tr><td><a href="./chat-note.html">chat-note.md</a></td><td><code>[[note:…]]</code></td><td>채팅</td></tr><tr><td><a href="./chat-folder.html">chat-folder.md</a></td><td><code>[[folder:…]]</code></td><td>채팅</td></tr><tr><td><a href="./chat-day-file-comments.html">chat-day-file-comments.md</a></td><td><code>&lt;!-- chat-msg … --&gt;</code> 등</td><td>채팅 일별 파일</td></tr><tr><td><a href="./enc-md.html">enc-md.md</a></td><td><code>.enc.md</code> vault 파일</td><td>암호화 노트</td></tr><tr><td><a href="./chat-saved-note.html">chat-saved-note.md</a></td><td><code>&lt;!-- chat-with-myself … --&gt;</code> + 카드</td><td>채팅→노트</td></tr><tr><td><a href="./note-cover.html">note-cover.md</a></td><td><code>&lt;!-- note-cover … --&gt;</code></td><td>인쇄 표지</td></tr><tr><td><a href="./haim-table.html">haim-table.md</a></td><td><code>&lt;!-- haim-table … --&gt;</code> + GFM 표</td><td>에디터 / 미리보기 / 인쇄 / 다운로드</td></tr><tr><td><a href="./plan-frontmatter.html">plan-frontmatter.md</a></td><td><code>---</code> YAML plan (<code>name</code> / <code>todos</code> / …)</td><td>에디터 / 미리보기 / 인쇄</td></tr><tr><td><a href="./footnotes.html">footnotes.md</a></td><td><code>[^1]</code> + <code>&lt;!-- footnotes {json} --&gt;</code></td><td>에디터 / 미리보기 / 인쇄</td></tr><tr><td><a href="./document-settings.html">document-settings.md</a></td><td><code>&lt;!-- document-settings {json} --&gt;</code></td><td>에디터 / 미리보기 / 인쇄</td></tr><tr><td><a href="./preview-hard-break.html">preview-hard-break.md</a></td><td><code>&lt;br/&gt;</code> (Mirror Edit Enter)</td><td>에디터 / 미리보기</td></tr><tr><td><a href="./mermaid-fence-size.html">mermaid-fence-size.md</a></td><td><code> ```mermaid width=… height=…</code> (legacy)</td><td>에디터 / 미리보기 / 인쇄</td></tr><tr><td><a href="./mermaid-size.html">mermaid-size.md</a></td><td><code>&lt;!-- mermaid-size … --&gt;</code> + mermaid fence</td><td>에디터 / 미리보기 / 인쇄</td></tr></tbody></table><h2 id="spec-conventions-all-features" tabindex="-1">Spec conventions (all features) <a class="header-anchor" href="#spec-conventions-all-features" aria-label="Permalink to “Spec conventions (all features)”">​</a></h2><p>Feature 문서의 <strong>Spec</strong> 섹션은 파서 중립 계약이다. markdown-it 토큰 이름은 참고용이며, 다른 엔진은 동등 AST/HTML이면 충분하다.</p><p>권장 구성:</p><ol><li><strong>Grammar</strong> — 정규식 / EBNF / 토큰 형태</li><li><strong>Parse algorithm</strong> — 단계·우선순위·실패 시 동작 (리터럴로 남김 등)</li><li><strong>Value normalization</strong> — 크기·색·escape 규칙</li><li><strong>Canonical HTML (or structured) output</strong> — 속성명·클래스·placeholder</li><li><strong>Post-process rules</strong> — caption fold, paragraph unwrap 등</li><li><strong>Non-goals / out of scope</strong> — hydration URL, UI 카드 등 앱 전용 단계</li></ol><p>공유 규칙:</p><table tabindex="0"><thead><tr><th>항목</th><th>계약</th></tr></thead><tbody><tr><td>Size value</td><td>bare digits → <code>Npx</code>; else allow <code>^\\d+(\\.\\d+)?(px|%|vh|vw)$</code> only</td></tr><tr><td>Hex color</td><td><code>#RGB</code> / <code>#RRGGBB</code> / <code>#RRGGBBAA</code> (optional <code>#</code>); expand 3→6; lowercase; reject <code>transparent</code>/<code>none</code>/non-hex → treat as absent</td></tr><tr><td>Placeholder img <code>src</code></td><td><code>data:image/gif;base64,R0lGODlhAQABAAAAACwAAAAAAQABAAA=</code> (1×1 transparent GIF) when real URL is resolved later</td></tr><tr><td>Style attr</td><td><code>width:…;height:…;background-color:…;</code> (omit empty parts; trailing <code>;</code> when non-empty)</td></tr><tr><td>HTML comment attrs</td><td><code>key=&quot;value&quot;</code> only; escape <code>&amp; &quot; &lt;</code> and newlines as <code>&amp;#10;</code> on write; reverse on read</td></tr></tbody></table><h2 id="커스텀이-아닌-것" tabindex="-1">커스텀이 아닌 것 <a class="header-anchor" href="#커스텀이-아닌-것" aria-label="Permalink to “커스텀이 아닌 것”">​</a></h2><p>다음을 새로 문서화하거나 “앱 전용 문법”으로 다루지 않는다.</p><ul><li>CommonMark / GFM (제목 h1–h6, 링크, 목록, 코드펜스, 테이블, task list 등)</li><li>md-editor-rt 기본 기능 (KaTeX, Mermaid, 이모지 등)</li><li>미리보기 외부 링크 <code>target=_blank</code> (<code>previewLinkTargetBlankPlugin</code>) — <strong>문법 아님</strong>, 렌더러만</li><li>녹음 동기화 — <code>.sync.pb</code> / <code>.sync.json</code> <strong>사이드카</strong>, 인라인 마커 없음</li><li>Obsidian식 일반 <code>[[wikilink]]</code> — <strong>미지원</strong> (<code>![[]]</code>, <code>[[file:]]</code>, <code>[[note:]]</code>, <code>[[folder:]]</code>만)</li></ul><h2 id="새-문법-추가-시" tabindex="-1">새 문법 추가 시 <a class="header-anchor" href="#새-문법-추가-시" aria-label="Permalink to “새 문법 추가 시”">​</a></h2><p>같은 변경에 <code>docs/custom-markdown/&lt;feature&gt;.md</code>(문법 + <strong>Spec</strong>)를 추가하고 이 표와 VitePress 사이드바(<code>docs/.vitepress/config.ts</code>)에 한 줄 넣는다.<br> Cursor rule: <code>.cursor/rules/custom-markdown-docs.mdc</code></p><p>사이트: 앱 배포 시 <code>{base}docs/</code> (로컬: <code>bun run docs:dev</code>).</p><p>VitePress용 디렉터리 인덱스는 <code>index.md</code>다 (<code>README.md</code> 아님).</p>',19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};